type snapshotExportRecord struct{Input SnapshotExportInput `json:"input"`;InputHash string `json:"inputHash"`;SnapshotID string `json:"snapshotId"`;State string `json:"state"`;Result *SnapshotExportResult `json:"result,omitempty"`;Manifest *DomainSnapshotManifest `json:"manifest,omitempty"`;SourceManifestHash string `json:"sourceManifestHash,omitempty"`;ResultHash string `json:"resultHash,omitempty"`}
type snapshotStageRecord struct{Input SnapshotStageInput `json:"input"`;HostEpoch string `json:"hostEpoch"`;Receipt SnapshotStageReceipt `json:"receipt"`;Manifest *DomainSnapshotManifest `json:"manifest,omitempty"`;TargetTree *SnapshotTree `json:"targetTree,omitempty"`;TreeFingerprint string `json:"treeFingerprint,omitempty"`;SourceManifestHash string `json:"sourceManifestHash,omitempty"`}
func (m *SnapshotManager) beginFileOperation(ctx context.Context,barrierID string)(SnapshotSafeCut,func(),error){
 unlock,err:=lockSnapshotControl(ctx,m.files);if err!=nil{return SnapshotSafeCut{},nil,err};view,err:=m.config.Runtime(ctx);if err!=nil{unlock();return SnapshotSafeCut{},nil,err};m.mu.Lock();if m.record==nil||!m.record.Input.Deadline.After(time.Now())||m.record.Status.State!="safe"||m.record.Input.BarrierID!=barrierID||view.BarrierID!=barrierID||view.DataEpoch!=m.record.Epoch||view.DataEpoch!=m.config.OpenedDataEpoch||!view.Maintenance||(view.Phase!=platform.PhaseBackupBarrier&&view.Phase!=platform.PhaseRestoreStaging){m.mu.Unlock();unlock();return SnapshotSafeCut{},nil,platform.NewError(platform.CodeLocked,true,"快照IO没有真实安全截点")};m.fileOps++;cut:=SnapshotSafeCut{BarrierID:barrierID,OperationID:m.record.Input.OperationID,Epoch:m.record.Epoch,Watermark:m.record.Status.RevisionWatermark};m.mu.Unlock();done:=func(){m.mu.Lock();m.fileOps--;m.signalLocked();m.mu.Unlock();unlock()};return cut,done,nil
}
func (m *SnapshotManager) Export(ctx context.Context,input SnapshotExportInput)(SnapshotExportResult,error){
 cut,done,err:=m.beginFileOperation(ctx,input.BarrierID);if err!=nil{return SnapshotExportResult{},err};defer done();if input.DataEpoch!=cut.Epoch{return SnapshotExportResult{},platform.NewError(platform.CodeVersionMismatch,false,"导出请求属于其他代次")};requestJSON,_:=platform.CanonicalJSON(input);hash:=platform.HashBytes(requestJSON);indexID:=platform.HashBytes([]byte(input.BackupID));recordPath:=filepath.Join(m.config.DataRoot,"control","snapshot-exports",indexID+".json");var record snapshotExportRecord
 if _,statErr:=os.Lstat(recordPath);statErr==nil{if err=readSnapshotJSON(recordPath,32<<20,&record);err!=nil{return SnapshotExportResult{},err};if record.InputHash!=hash||record.Input.BackupID!=input.BackupID||!platform.ValidIdentifier(record.SnapshotID){return SnapshotExportResult{},platform.NewError(platform.CodeConflict,false,"同备份导出原输入不同")}}else if !errors.Is(statErr,os.ErrNotExist){return SnapshotExportResult{},snapshotIOError(statErr)}else{record=snapshotExportRecord{Input:input,InputHash:hash,SnapshotID:platform.NewIdentifier(),State:"preparing"};if err=writeSnapshotJSON(recordPath,m.config.DataRoot,record);err!=nil{return SnapshotExportResult{},err}}
 base:=filepath.Join(m.config.DataRoot,"control","snapshot-archives",record.SnapshotID);final:=filepath.Join(base,"archive.tar");temporary:=filepath.Join(base,".archive.tmp");workspace:=filepath.Join(base,"capture")
 if record.State=="complete"||record.State=="archive-prepared"{if record.Result==nil||record.Manifest==nil{return SnapshotExportResult{},integrity("导出完成证据缺失")};if err=verifySnapshotExportRecord(record);err!=nil{return SnapshotExportResult{},err};ref:=record.Result.Snapshot.Object;if record.Result.Snapshot.SnapshotID!=record.SnapshotID||ref.Owner!=m.config.Owner||record.Result.Checksum!=ref.SHA256{return SnapshotExportResult{},integrity("导出完成回执损坏")};if _,statErr:=os.Lstat(final);errors.Is(statErr,os.ErrNotExist){if err=verifySnapshotFile(ctx,temporary,DomainSnapshotFile{ByteSize:ref.ByteSize,SHA256:ref.SHA256});err!=nil{return SnapshotExportResult{},err};if err=os.Rename(temporary,final);err!=nil{return SnapshotExportResult{},snapshotIOError(err)};if err=syncSnapshotDirectories(base,m.config.DataRoot);err!=nil{return SnapshotExportResult{},err}};if err=verifySnapshotFile(ctx,final,DomainSnapshotFile{ByteSize:ref.ByteSize,SHA256:ref.SHA256});err!=nil{return SnapshotExportResult{},err};record.State="complete";if err=writeSnapshotJSON(recordPath,m.config.DataRoot,record);err!=nil{return SnapshotExportResult{},err};if err=writeSnapshotJSON(filepath.Join(base,"complete.json"),m.config.DataRoot,record);err!=nil{return SnapshotExportResult{},err};return *record.Result,nil}
 if record.State!="preparing"{return SnapshotExportResult{},integrity("导出journal状态未知")};if err=snapshotDirectory(base,m.config.DataRoot);err!=nil{return SnapshotExportResult{},err};if _,statErr:=os.Lstat(final);!errors.Is(statErr,os.ErrNotExist){return SnapshotExportResult{},integrity("未完成导出已有未知最终归档")};if err=removeSnapshotTree(workspace);err!=nil{return SnapshotExportResult{},err};if err=snapshotDirectory(filepath.Join(workspace,"files"),m.config.DataRoot);err!=nil{return SnapshotExportResult{},err};if err=ValidatePrivatePath(temporary,"regular-file",true);err!=nil{return SnapshotExportResult{},err};if err=os.Remove(temporary);err!=nil&&!errors.Is(err,os.ErrNotExist){return SnapshotExportResult{},snapshotIOError(err)}
 captureInput:=input;captureInput.SnapshotID=record.SnapshotID;manifest,err:=m.config.Capture(context.WithValue(ctx,snapshotCaptureKey{},m),cut,workspace,captureInput);if err!=nil{return SnapshotExportResult{},err};if manifest.Owner!=m.config.Owner||manifest.BackupID!=input.BackupID||manifest.BarrierID!=cut.BarrierID||manifest.SnapshotID!=record.SnapshotID||manifest.SourceEpoch!=cut.Epoch||manifest.RevisionWatermark!=cut.Watermark||(manifest.ContainsSecrets&&!input.IncludeSecrets){return SnapshotExportResult{},integrity("真实捕获清单与固定安全截点不符")};archive,err:=BuildSnapshotArchive(ctx,workspace,temporary,manifest,m.config.ValidateManifest);if err!=nil{return SnapshotExportResult{},err};if err=syncSnapshotDirectories(base,m.config.DataRoot);err!=nil{return SnapshotExportResult{},err};ref:=SnapshotRef{Owner:m.config.Owner,SnapshotID:record.SnapshotID,DataEpoch:cut.Epoch,DataSchemaVersion:manifest.DataSchemaVersion,RevisionWatermark:cut.Watermark,ContainsSecrets:manifest.ContainsSecrets,Object:platform.ObjectRef{Owner:m.config.Owner,ObjectID:record.SnapshotID,Version:1,SHA256:archive.SHA256,ByteSize:archive.ByteSize,MediaType:"application/x-tar"}};record.Manifest=&manifest;record.SourceManifestHash=archive.ManifestHash;record.Result=&SnapshotExportResult{Snapshot:ref,Checksum:ref.Object.SHA256};resultRaw,_:=platform.CanonicalJSON(record.Result);record.ResultHash=platform.HashBytes(resultRaw);record.State="archive-prepared";if err=writeSnapshotJSON(recordPath,m.config.DataRoot,record);err!=nil{return SnapshotExportResult{},err};if err=os.Rename(temporary,final);err!=nil{return SnapshotExportResult{},snapshotIOError(err)};if err=syncSnapshotDirectories(base,m.config.DataRoot);err!=nil{return SnapshotExportResult{},err};record.State="complete";if err=writeSnapshotJSON(recordPath,m.config.DataRoot,record);err!=nil{return SnapshotExportResult{},err};if err=writeSnapshotJSON(filepath.Join(base,"complete.json"),m.config.DataRoot,record);err!=nil{return SnapshotExportResult{},err};return *record.Result,nil
}
// OpenArchive仅开本域真实完成归档。接收方仍按期望ObjectRef做全流hash/EOF核验。
func (m *SnapshotManager) OpenArchive(ctx context.Context,snapshotID string,expected platform.ObjectRef)(io.ReadCloser,error){
 if !platform.ValidIdentifier(snapshotID)||expected.Owner!=m.config.Owner||expected.ObjectID!=snapshotID||expected.Version!=1||expected.MediaType!="application/x-tar"{return nil,integrity("归档读取绑定不合法")};base:=filepath.Join(m.config.DataRoot,"control","snapshot-archives",snapshotID);var record snapshotExportRecord;if err:=readSnapshotJSON(filepath.Join(base,"complete.json"),32<<20,&record);err!=nil{return nil,err};if record.Result==nil||record.Manifest==nil{return nil,integrity("导出完成证据缺失")};if err:=verifySnapshotExportRecord(record);err!=nil{return nil,err};expectedJSON,_:=platform.CanonicalJSON(expected);storedJSON,_:=platform.CanonicalJSON(record.Result.Snapshot.Object);if record.State!="complete"||record.SnapshotID!=snapshotID||string(expectedJSON)!=string(storedJSON){return nil,integrity("归档尚未真实完成或期望引用不符")};path:=filepath.Join(base,"archive.tar");if err:=verifySnapshotFile(ctx,path,DomainSnapshotFile{ByteSize:expected.ByteSize,SHA256:expected.SHA256});err!=nil{return nil,err};source,err:=os.Open(path);if err!=nil{return nil,snapshotIOError(err)};return source,nil
}
func removeSnapshotTree(path string)error{if _,err:=os.Lstat(path);errors.Is(err,os.ErrNotExist){return nil};if err:=ValidatePrivatePath(path,"directory",false);err!=nil{return err};if err:=filepath.WalkDir(path,func(item string,entry os.DirEntry,walkErr error)error{if walkErr!=nil{return snapshotIOError(walkErr)};kind:="regular-file";if entry.IsDir(){kind="directory"};return ValidatePrivatePath(item,kind,false)});err!=nil{return err};return snapshotIOError(os.RemoveAll(path))}
func fingerprintSnapshotTree(ctx context.Context,root string,limit int64)(SnapshotTree,string,error){
 tree:=SnapshotTree{Files:[]DomainSnapshotFile{},Directories:[]string{}};var total int64
 if limit<0||limit>MaxArchiveBytes{return tree,"",snapshotBudget("目标树容量未知或超上限")}
 err:=filepath.WalkDir(root,func(path string,entry os.DirEntry,walkErr error)error{
  if walkErr!=nil{return snapshotIOError(walkErr)};if err:=ctx.Err();err!=nil{return snapshotIOError(err)}
  relative,err:=filepath.Rel(root,path);if err!=nil{return snapshotIOError(err)};relative=filepath.ToSlash(relative)
  if path==root{return ValidatePrivatePath(path,"directory",false)}
  if !safeSnapshotRelative(relative){return integrity("迁移目标路径不合法")}
  if len(tree.Files)+len(tree.Directories)>=MaxArchiveFiles{return snapshotBudget("目标文件与目录总数超预算")}
  if entry.IsDir(){if err=ValidatePrivatePath(path,"directory",false);err!=nil{return err};tree.Directories=append(tree.Directories,relative);return nil}
  if err=ValidatePrivatePath(path,"regular-file",false);err!=nil{return err};f,err:=os.Open(path);if err!=nil{return snapshotIOError(err)};defer f.Close();info,err:=f.Stat();if err!=nil{return snapshotIOError(err)};if info.Size()>limit-total{return snapshotBudget("迁移目标空间超过真实计划")};total+=info.Size();digest:=sha256.New();buffer:=make([]byte,128<<10);bounded:=io.LimitReader(f,info.Size()+1);var readBytes int64
  for{if err=ctx.Err();err!=nil{return snapshotIOError(err)};n,readErr:=bounded.Read(buffer);readBytes+=int64(n);if n>0{_,_=digest.Write(buffer[:n])};if errors.Is(readErr,io.EOF){break};if readErr!=nil{return snapshotIOError(readErr)}}
  if readBytes!=info.Size(){return integrity("迁移目标文件读取期间改变长度")};tree.Files=append(tree.Files,DomainSnapshotFile{Path:relative,SHA256:hex.EncodeToString(digest.Sum(nil)),ByteSize:info.Size()});return nil
 });if err!=nil{return SnapshotTree{},"",err}
 sort.Slice(tree.Files,func(i,j int)bool{return tree.Files[i].Path<tree.Files[j].Path});sort.Strings(tree.Directories);raw,_:=platform.CanonicalJSON(tree);if int64(len(raw))>MaxManifestBytes{return SnapshotTree{},"",snapshotBudget("目标树指纹清单超预算")};return tree,platform.HashBytes(raw),nil
}
func snapshotStageID(restoreID,snapshotID string)string{raw,_:=platform.CanonicalJSON([]string{restoreID,snapshotID});return platform.HashBytes(raw)}
func verifySnapshotTarget(ctx context.Context,root string,record snapshotStageRecord)error{
 if record.TargetTree==nil||record.TargetTree.Files==nil||record.TargetTree.Directories==nil||record.TreeFingerprint==""{return integrity("暂存完整目标树证明缺失")};raw,_:=platform.CanonicalJSON(record.TargetTree);if platform.HashBytes(raw)!=record.TreeFingerprint||record.Receipt.ManifestHash!=record.TreeFingerprint{return integrity("暂存目标树指纹损坏")}
 _,hash,err:=fingerprintSnapshotTree(ctx,root,MaxArchiveBytes);if err!=nil{return err};if hash!=record.TreeFingerprint{return integrity("暂存完整目标树已改变")};return nil
}
func (m *SnapshotManager) Stage(ctx context.Context,input SnapshotStageInput,source io.Reader)(SnapshotStageResult,error){
 _,done,err:=m.beginFileOperation(ctx,input.BarrierID);if err!=nil{return SnapshotStageResult{},err};defer done();view,err:=m.config.Runtime(ctx);if err!=nil{return SnapshotStageResult{},err};if view.Phase!=platform.PhaseRestoreStaging||view.RestoreID!=input.RestoreID||view.TargetDataEpoch!=input.TargetDataEpoch||view.DataEpoch==input.TargetDataEpoch||input.Snapshot.Owner!=m.config.Owner||input.Snapshot.Object.Owner!=m.config.Owner||input.Snapshot.Object.ObjectID!=input.Snapshot.SnapshotID||input.Snapshot.Object.Version!=1||input.Snapshot.Object.MediaType!="application/x-tar"||input.Checksum!=input.Snapshot.Object.SHA256{return SnapshotStageResult{},integrity("暂存请求与恢复权威/源归档不符")};inputJSON,_:=platform.CanonicalJSON(input);inputHash:=platform.HashBytes(inputJSON);recordPath:=filepath.Join(m.config.DataRoot,"control","snapshot-stages",input.RestoreID+".json");var record snapshotStageRecord
 if _,statErr:=os.Lstat(recordPath);statErr==nil{if err=readSnapshotJSON(recordPath,48<<20,&record);err!=nil{return SnapshotStageResult{},err};if record.HostEpoch!=view.DataEpoch||record.Receipt.InputHash!=inputHash||record.Receipt.RestoreID!=input.RestoreID||record.Receipt.StageID!=snapshotStageID(input.RestoreID,input.Snapshot.SnapshotID){return SnapshotStageResult{},platform.NewError(platform.CodeConflict,false,"暂存原输入不符")}}else if !errors.Is(statErr,os.ErrNotExist){return SnapshotStageResult{},snapshotIOError(statErr)}else{record=snapshotStageRecord{Input:input,HostEpoch:view.DataEpoch,Receipt:SnapshotStageReceipt{RestoreID:input.RestoreID,StageID:snapshotStageID(input.RestoreID,input.Snapshot.SnapshotID),SnapshotID:input.Snapshot.SnapshotID,SourceEpoch:input.Snapshot.DataEpoch,TargetEpoch:input.TargetDataEpoch,InputHash:inputHash,State:"preparing"}};if err=writeSnapshotJSON(recordPath,m.config.DataRoot,record);err!=nil{return SnapshotStageResult{},err}}
 base:=filepath.Join(m.config.DataRoot,"restore",input.RestoreID);temporary:=filepath.Join(base,".stage-"+record.Receipt.StageID);staged:=filepath.Join(base,"staged");if record.Receipt.State=="staged"||record.Receipt.State=="prepared-stage"{return m.finishStage(ctx,recordPath,temporary,staged,record,true)};if record.Receipt.State!="preparing"{return SnapshotStageResult{},integrity("暂存journal状态未知")};if _,statErr:=os.Lstat(staged);!errors.Is(statErr,os.ErrNotExist){return SnapshotStageResult{},integrity("未完成暂存存在未知staged目录")};if err=removeSnapshotTree(temporary);err!=nil{return SnapshotStageResult{},err};if err=snapshotDirectory(temporary,m.config.DataRoot);err!=nil{return SnapshotStageResult{},err};archive,err:=ExtractSnapshotArchive(ctx,source,temporary,input.Snapshot.Object,m.config.ValidateManifest);if err!=nil{return SnapshotStageResult{},err};manifest:=archive.Manifest;if manifest.Owner!=m.config.Owner||manifest.SnapshotID!=input.Snapshot.SnapshotID||manifest.SourceEpoch!=input.Snapshot.DataEpoch||manifest.DataSchemaVersion!=input.Snapshot.DataSchemaVersion||manifest.RevisionWatermark!=input.Snapshot.RevisionWatermark||manifest.ContainsSecrets!=input.Snapshot.ContainsSecrets{return SnapshotStageResult{},integrity("源归档清单与SnapshotRef不符")};planBytes,err:=m.config.StageBudget(ctx,manifest);if err!=nil{return SnapshotStageResult{},err};var sourceBytes int64;for _,file:=range manifest.Files{sourceBytes+=file.ByteSize};if planBytes<sourceBytes||planBytes>MaxArchiveBytes{return SnapshotStageResult{},snapshotBudget("迁移完整空间计划小于源文件或未知")};if err=CheckSnapshotDiskBudget(ctx,base,planBytes-sourceBytes);err!=nil{return SnapshotStageResult{},err};if err=m.config.MigrateStage(context.WithValue(ctx,snapshotStageScopeKey{},&snapshotStageScope{manager:m,input:input,root:temporary}),manifest,input.TargetDataEpoch,temporary);err!=nil{return SnapshotStageResult{},err};if err=m.config.ValidateStaged(ctx,manifest,input.TargetDataEpoch,temporary);err!=nil{return SnapshotStageResult{},err}
 // paid/body权威文件必须保持原hash，迁移只能按域合同改变索引，不通用改不可变对象。
 for _,object:=range manifest.Objects{if err=verifySnapshotFile(ctx,filepath.Join(temporary,filepath.FromSlash(object.Path)),DomainSnapshotFile{ByteSize:object.Reference.ByteSize,SHA256:object.Reference.SHA256});err!=nil{return SnapshotStageResult{},err}};tree,fingerprint,err:=fingerprintSnapshotTree(ctx,temporary,planBytes);if err!=nil{return SnapshotStageResult{},err};for _,file:=range tree.Files{path:=filepath.Join(temporary,filepath.FromSlash(file.Path));f,openErr:=os.Open(path);if openErr!=nil{return SnapshotStageResult{},snapshotIOError(openErr)};syncErr:=f.Sync();_ = f.Close();if syncErr!=nil{return SnapshotStageResult{},snapshotIOError(syncErr)};if err=syncSnapshotDirectories(filepath.Dir(path),m.config.DataRoot);err!=nil{return SnapshotStageResult{},err}};for i:=len(tree.Directories)-1;i>=0;i--{if err=syncSnapshotDirectories(filepath.Join(temporary,filepath.FromSlash(tree.Directories[i])),m.config.DataRoot);err!=nil{return SnapshotStageResult{},err}};if err=syncSnapshotDirectories(temporary,m.config.DataRoot);err!=nil{return SnapshotStageResult{},err};record.Manifest=&manifest;record.TargetTree=&tree;record.TreeFingerprint=fingerprint;record.SourceManifestHash=archive.ManifestHash;record.Receipt.ManifestHash=fingerprint;record.Receipt.State="prepared-stage";if err=writeSnapshotJSON(recordPath,m.config.DataRoot,record);err!=nil{return SnapshotStageResult{},err};return m.finishStage(ctx,recordPath,temporary,staged,record,false)
}
func (m *SnapshotManager) finishStage(ctx context.Context,recordPath,temporary,staged string,record snapshotStageRecord,recovered bool)(SnapshotStageResult,error){
 view,err:=m.config.Runtime(ctx);if err!=nil{return SnapshotStageResult{},err};if view.Phase!=platform.PhaseRestoreStaging||!view.Maintenance||view.DataEpoch!=record.HostEpoch||view.BarrierID!=record.Input.BarrierID||view.RestoreID!=record.Input.RestoreID||view.TargetDataEpoch!=record.Input.TargetDataEpoch{return SnapshotStageResult{},platform.NewError(platform.CodeLocked,false,"暂存完成前全局恢复决定已变化")}
 if recovered{if record.Manifest==nil{return SnapshotStageResult{},integrity("暂存缺真实源清单")};inputJSON,_:=platform.CanonicalJSON(record.Input);manifestJSON,manifestErr:=validateSnapshotInventory(*record.Manifest,m.config.ValidateManifest);if manifestErr!=nil{return SnapshotStageResult{},manifestErr};if platform.HashBytes(inputJSON)!=record.Receipt.InputHash||platform.HashBytes(manifestJSON)!=record.SourceManifestHash||record.Manifest.Owner!=m.config.Owner||record.Manifest.SnapshotID!=record.Input.Snapshot.SnapshotID||record.Receipt.SnapshotID!=record.Input.Snapshot.SnapshotID||record.Receipt.TargetEpoch!=record.Input.TargetDataEpoch||record.Receipt.SourceEpoch!=record.Manifest.SourceEpoch||record.Manifest.SourceEpoch!=record.Input.Snapshot.DataEpoch||record.Manifest.DataSchemaVersion!=record.Input.Snapshot.DataSchemaVersion||record.Manifest.RevisionWatermark!=record.Input.Snapshot.RevisionWatermark||record.Manifest.ContainsSecrets!=record.Input.Snapshot.ContainsSecrets{return SnapshotStageResult{},integrity("暂存控制回执与原输入/源清单不符")}}
 root:=temporary;if _,err:=os.Lstat(staged);err==nil{exists,tempErr:=snapshotDirectoryExists(temporary);if tempErr!=nil{return SnapshotStageResult{},tempErr};if exists{return SnapshotStageResult{},integrity("暂存目录与临时目录同时存在，不猜测使用哪个")};root=staged}else if !errors.Is(err,os.ErrNotExist){return SnapshotStageResult{},snapshotIOError(err)};if recovered{if err:=verifySnapshotTarget(ctx,root,record);err!=nil{return SnapshotStageResult{},err};if err:=m.config.ValidateStaged(ctx,*record.Manifest,record.Input.TargetDataEpoch,root);err!=nil{return SnapshotStageResult{},err}};if root==temporary{if err:=os.Rename(temporary,staged);err!=nil{return SnapshotStageResult{},snapshotIOError(err)};if err:=syncSnapshotDirectories(filepath.Dir(staged),m.config.DataRoot);err!=nil{return SnapshotStageResult{},err}};record.Receipt.State="staged";if err:=writeSnapshotJSON(recordPath,m.config.DataRoot,record);err!=nil{return SnapshotStageResult{},err};return SnapshotStageResult{RestoreID:record.Input.RestoreID,Owner:m.config.Owner,SnapshotID:record.Input.Snapshot.SnapshotID,TargetDataEpoch:record.Input.TargetDataEpoch,Checksum:record.Input.Checksum,Staged:true,StageID:record.Receipt.StageID,ManifestHash:record.TreeFingerprint},nil
}
func (m *SnapshotManager) Discard(ctx context.Context,input SnapshotDiscardInput)(SnapshotDiscardResult,error){
 unlock,err:=lockSnapshotControl(ctx,m.files);if err!=nil{return SnapshotDiscardResult{},err};defer unlock();if !platform.ValidIdentifier(input.RestoreID)||(input.Scope!="staged"&&input.Scope!="before"){return SnapshotDiscardResult{},integrity("丢弃请求不合法")};record,err:=readSnapshotStageRecord(m.config.DataRoot,input.RestoreID);recordPath:=filepath.Join(m.config.DataRoot,"control","snapshot-stages",input.RestoreID+".json");if err!=nil{return SnapshotDiscardResult{},err};view,err:=m.config.Runtime(ctx);if err!=nil{return SnapshotDiscardResult{},err};if view.DataEpoch!=m.config.OpenedDataEpoch{return SnapshotDiscardResult{},platform.NewError(platform.CodeVersionMismatch,false,"已打开数据未对齐当前代次")};swap,err:=ReadRestoreSwapState(m.config.DataRoot,input.RestoreID);if err!=nil{return SnapshotDiscardResult{},err};if !swap.Known{return SnapshotDiscardResult{},integrity("本域换目录事实尚未完整证明")};allowed:=false
 if input.Scope=="staged"{allowed=view.Phase==platform.PhaseRestoreStaging&&view.Maintenance&&view.RestoreID==input.RestoreID&&!swap.Switched&&!swap.RolledBack;allowed=allowed||(view.Phase==platform.PhaseRunning&&!view.Maintenance&&view.DataEpoch==record.HostEpoch&&(swap.RolledBack||swap.Aborted))}else{allowed=view.Phase==platform.PhaseRunning&&!view.Maintenance&&view.DataEpoch==record.Input.TargetDataEpoch&&swap.Switched&&!swap.RolledBack};if !allowed{return SnapshotDiscardResult{},platform.NewError(platform.CodeLocked,true,"当前全局决定不允许丢弃该数据目录")};path:=filepath.Join(m.config.DataRoot,"restore",input.RestoreID,input.Scope);exists,err:=snapshotDirectoryExists(path);if err!=nil{return SnapshotDiscardResult{},err};if record.Receipt.State=="discarded-"+input.Scope{if exists{return SnapshotDiscardResult{},integrity("已丢弃目录重新出现，拒绝删除未知数据")};return SnapshotDiscardResult{RestoreID:input.RestoreID,Scope:input.Scope,Removed:false},nil};if exists&&record.Receipt.State!="discarding-"+input.Scope{if input.Scope=="staged"{if err=verifySnapshotTarget(ctx,path,record);err!=nil{return SnapshotDiscardResult{},err}}else{if err=verifySnapshotHash(path,swap.HostManifestHash);err!=nil{return SnapshotDiscardResult{},err}}};record.Receipt.State="discarding-"+input.Scope;if err=writeSnapshotJSON(recordPath,m.config.DataRoot,record);err!=nil{return SnapshotDiscardResult{},err};if exists{if err=removeSnapshotTree(path);err!=nil{return SnapshotDiscardResult{},err}};if err=syncSnapshotDirectories(filepath.Dir(path),m.config.DataRoot);err!=nil{return SnapshotDiscardResult{},err};record.Receipt.State="discarded-"+input.Scope;if err=writeSnapshotJSON(recordPath,m.config.DataRoot,record);err!=nil{return SnapshotDiscardResult{},err};return SnapshotDiscardResult{RestoreID:input.RestoreID,Scope:input.Scope,Removed:exists},nil
}

func verifySnapshotExportRecord(record snapshotExportRecord)error{
 if record.Manifest==nil||record.Result==nil{return integrity("导出完成证据缺失")};input,_:=platform.CanonicalJSON(record.Input);manifest,_:=platform.CanonicalJSON(record.Manifest);result,_:=platform.CanonicalJSON(record.Result)
 ref:=record.Result.Snapshot
 if record.InputHash!=platform.HashBytes(input)||record.SourceManifestHash!=platform.HashBytes(manifest)||record.ResultHash!=platform.HashBytes(result)||ref.SnapshotID!=record.SnapshotID||ref.DataEpoch!=record.Input.DataEpoch||ref.Owner!=record.Manifest.Owner||ref.SnapshotID!=record.Manifest.SnapshotID||ref.DataEpoch!=record.Manifest.SourceEpoch||ref.DataSchemaVersion!=record.Manifest.DataSchemaVersion||ref.RevisionWatermark!=record.Manifest.RevisionWatermark||ref.ContainsSecrets!=record.Manifest.ContainsSecrets||record.Manifest.BackupID!=record.Input.BackupID||record.Manifest.BarrierID!=record.Input.BarrierID||ref.Object.ObjectID!=ref.SnapshotID||ref.Object.Owner!=ref.Owner||ref.Object.Version!=1||ref.Object.MediaType!="application/x-tar"||record.Result.Checksum!=ref.Object.SHA256{return integrity("导出原输入/源清单/完整引用回执不一致")};return nil
}
